sys_ui_action.script:
// Validate that a maintenance issue comment is present before proceeding 
if (!current.close_notes || current.close_notes.toString().trim() == '') { 
    gs.addErrorMessage('A comment is required in the Maintenance issue field before flagging for maintenance.'); 
 action.setRedirectURL(current); 
} else { 
    // Create the Workspace Maintenance record 
    var maint = new GlideRecord('x_2225841_wrm_workspace_maintenance'); 
    maint.initialize(); 
    maint.reservation = current.getUniqueValue(); 
    maint.workspace = current.workspace; 
    maint.workspace_status = '1'; 
    maint.ticket_status = '1'; 
    maint.date_reported = new GlideDateTime().getLocalDate(); 
    maint.issue_description = current.close_notes; 

    // Assign to Workspace Maintenance Team 
    var grp = new GlideRecord('sys_user_group'); 
    grp.addQuery('name', 'Workspace Maintenance Team'); 
    grp.query(); 
    if (grp.next()) { 
        maint.assignment_group = grp.getUniqueValue(); 
    } 

    var newId = maint.insert(); 
    if (newId) { 
        gs.addInfoMessage('Maintenance ticket created successfully.'); 
        current.sent_to_maintenance = true; 
        current.update(); 
        action.setRedirectURL(current); 
    } else { 
        gs.addErrorMessage('Failed to create the maintenance ticket. Please contact an administrator.'); 
    } 
}
